/* /cgi-bin/orders.c - one program per page (RFC 3875) */
int main(void) {
    const char *method = getenv("REQUEST_METHOD");
    char qs[256];
    if (!read_query(qs, sizeof qs)) return send_400();   /* QUERY_STRING */
    require_session_or_302();                            /* shared check */
    Order o;
    if (strcmp(method, "POST") == 0 && parse_order(qs, &o))
        place_order(&o);                                 /* domain logic */
    fputs("Content-Type: text/html\r\n\r\n", stdout);
    return render_orders(stdout, list_orders());         /* view */
}
